def f(g):
    o=[r[:] for r in g]; H,W=len(g),len(g[0]); C=set(r[c] for r in g for c in range(W))
    cols={c:set(i for i in range(H) if g[i][c]==4) for c in range(W)}
    rows={i:{j for j in range(W) if g[i][j]==4} for i in range(H)}
    for i in range(H):
        rs=sorted(rows[i])
        for x in rs:
            L=next((y for y in rs if y<x),None); R=next((y for y in rs if y>x),None)
            if L is not None and R is not None:
                for j in range(L+1,R):
