from collections import deque
def enclosed(g):
    H,W=len(g),len(g[0])
    seen=[[False]*W for _ in range(H)]; q=deque()
    for i in [0,H-1]:
        for j in range(W):
            if g[i][j]!=8: continue
            if not seen[i][j]: seen[i][j]=True; q.append((i,j))
    for j in [0,W-1]:
        for i in range(H):
            if g[i][j]!=8: continue
            if not seen[i][j]: seen[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<H and 0<=nj<W and g[ni][nj]==8 and not seen[ni][nj]:
                seen[ni][nj]=True; q.append((ni,nj))
    return [[g[i][j] if not seen[i][j] else 2 for j in range(W)] for i in range(H)]
